const [pending, setPending] = useState<{ id: string } | null>(null);
<Confirmation
  open={pending !== null}
  onOpenChange={(o) => !o && setPending(null)}
  title="Approve agent action?"
  description={pending?.id ? `Run tool ${pending.id}` : ""}
  severity="warning"
  onConfirm={() => approve(pending!.id)}
  onCancel={() => deny(pending!.id)}
/>
